// Test fixture: type-only stand-in for @sitecore-content-sdk/nextjs.
// Content SDK re-exports the same field type names as JSS (from @sitecore-content-sdk/content/layout);
// the declaring path is what lets the plugin tell the two packages apart.

export interface Field<T = unknown> {
  value: T;
  editable?: string;
}

export interface TextField {
  value?: string | number;
  editable?: string;
}

export interface RichTextField {
  value?: string;
  editable?: string;
}

export interface ImageFieldValue {
  [attributeName: string]: unknown;
  src?: string;
  alt?: string;
  width?: string | number;
  height?: string | number;
}

export interface ImageField {
  value?: ImageFieldValue;
  editable?: string;
}

export interface LinkFieldValue {
  [attributeName: string]: unknown;
  href?: string;
  className?: string;
  class?: string;
  title?: string;
  target?: string;
  text?: string;
  anchor?: string;
}

export interface LinkField {
  value: LinkFieldValue;
  editableFirstPart?: string;
  editableLastPart?: string;
}

export interface FileFieldValue {
  [propName: string]: unknown;
  src?: string;
  title?: string;
  displayName?: string;
}

export interface FileField {
  value: FileFieldValue;
}

type Attributes = { [attributeName: string]: unknown };

export declare const Text: (
  props: Attributes & { field?: TextField; tag?: string; editable?: boolean; encode?: boolean }
) => unknown;
export declare const RichText: (
  props: Attributes & { field?: RichTextField; tag?: string; editable?: boolean }
) => unknown;
export declare const Image: (
  props: Attributes & { field?: ImageField | ImageFieldValue; editable?: boolean }
) => unknown;
export declare const NextImage: (
  props: Attributes & { field?: ImageField | ImageFieldValue; editable?: boolean }
) => unknown;
export declare const Link: (
  props: Attributes & {
    field: LinkField | LinkFieldValue;
    editable?: boolean;
    showLinkTextWithChildrenPresent?: boolean;
    children?: unknown;
  }
) => unknown;
export declare const File: (
  props: Attributes & { field: FileField | FileFieldValue; children?: unknown }
) => unknown;
export declare const DateField: (
  props: Attributes & { field?: Field<string>; tag?: string; render?: (date: Date | null) => unknown }
) => unknown;
